import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int y;
        int capacity;
        int flow;
        int cost;

        Edge(int y, int capacity, int flow, int cost) {
            this.y = y;
            this.capacity = capacity;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static final long INF64 = (long)1e18;
    static final int MAXNODES = 1000007;
    static List<Integer>[] adjList = new ArrayList[MAXNODES];
    static List<Edge> edgeList = new ArrayList<>();
    static long totalCostSum = 0;
    static long[] distArray = new long[MAXNODES];
    static int[] predArray = new int[MAXNODES];
    static int[] peArray = new int[MAXNODES];
    static int[] inQ = new int[MAXNODES];

    static int sNode = MAXNODES - 2;
    static int tNode = MAXNODES - 1;

    static int n, m, k, c, d;

    static int modVal(int a) {
        return ((a % 1000000007) + 1000000007) % 1000000007;
    }

    static int prod(int a, int b) {
        return (int)((a * 1L * b) % 1000000007);
    }

    static int fastExponent(int a, int k) {
        int res = 1;
        while (k > 0) {
            if ((k & 1) != 0) res = prod(res, a);
            a = prod(a, a);
            k >>= 1;
        }
        return res;
    }

    static int getInverse(int a) {
        int b = fastExponent(a, 1000000007 - 2);
        assert prod(a, b) == 1;
        return b;
    }

    static int residualCap(int x) {
        Edge e = edgeList.get(x);
        return e.capacity - e.flow;
    }

    static void findFlow() {
        Arrays.fill(distArray, INF64);
        Arrays.fill(predArray, -1);
        Arrays.fill(peArray, -1);
        Arrays.fill(inQ, 0);
        distArray[sNode] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(sNode);
        inQ[sNode] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            inQ[u] = 0;
            for (int eIdx : adjList[u]) {
                if (residualCap(eIdx) == 0) continue;
                Edge e = edgeList.get(eIdx);
                int y = e.y;
                if (distArray[y] > distArray[u] + e.cost) {
                    distArray[y] = distArray[u] + e.cost;
                    predArray[y] = u;
                    peArray[y] = eIdx;
                    if (inQ[y] == 0) {
                        inQ[y] = 1;
                        q.offer(y);
                    }
                }
            }
        }
        int cur = tNode;
        while (cur != sNode) {
            int eIdx = peArray[cur];
            edgeList.get(eIdx).flow++;
            edgeList.get(eIdx ^ 1).flow--;
            cur = predArray[cur];
        }
        totalCostSum += distArray[tNode];
    }

    static void addEdgeToGraph(int x, int y, int cap, int cst) {
        adjList[x].add(edgeList.size());
        edgeList.add(new Edge(y, cap, 0, cst));
        adjList[y].add(edgeList.size());
        edgeList.add(new Edge(x, 0, 0, -cst));
    }

    static void readDataSet(Scanner sc) {
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();

        for (int i = 0; i < MAXNODES; i++) {
            adjList[i] = new ArrayList<>();
        }

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt() - 1;
            addEdgeToGraph(sNode, x, 1, 0);
        }

        int layersCount = 101;
        for (int i = 0; i < layersCount; i++) {
            addEdgeToGraph(i * n, tNode, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            for (int t = 0; t < layersCount - 1; t++) {
                for (int j = 0; j < k; j++) {
                    addEdgeToGraph(x + t * n, y + t * n + n, 1, d * (j * 2 + 1));
                }
            }
            for (int t = 0; t < layersCount - 1; t++) {
                for (int j = 0; j < k; j++) {
                    addEdgeToGraph(y + t * n, x + t * n + n, 1, d * (j * 2 + 1));
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < layersCount - 1; j++) {
                addEdgeToGraph(i + j * n, i + j * n + n, k, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            findFlow();
        }

        System.out.println(totalCostSum);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        readDataSet(sc);
        sc.close();
    }
}
